<?php
session_start();
require __DIR__ . '/../../config/db_connection.php';
if (!isset($_SESSION['admin_id'])) { header('Location: admin_login.php'); exit; }
if (empty($_SESSION['admin_support_csrf'])) $_SESSION['admin_support_csrf'] = bin2hex(random_bytes(32));
$message = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $type = $_POST['account_type'] ?? ''; $id = (int)($_POST['account_id'] ?? 0); $temporary = $_POST['temporary_password'] ?? '';
    $strong = strlen($temporary) >= 8 && preg_match('/[a-z]/',$temporary) && preg_match('/[A-Z]/',$temporary) && preg_match('/\d/',$temporary) && preg_match('/[^a-zA-Z\d]/',$temporary);
    if (!hash_equals($_SESSION['admin_support_csrf'], $_POST['csrf_token'] ?? '')) $error = 'Your session expired. Refresh the page and try again.';
    elseif (!in_array($type, ['student','seller'], true) || !$id) $error = 'Choose the account that needs support.';
    elseif (!$strong) $error = 'Use 8+ characters with uppercase, lowercase, a number, and a special character.';
    else {
        $table = $type === 'student' ? 'students' : 'sellers';
        $stmt = $conn->prepare("UPDATE $table SET password=? WHERE id=?"); $hash = password_hash($temporary, PASSWORD_DEFAULT); $stmt->bind_param('si',$hash,$id); $stmt->execute(); $changed = $stmt->affected_rows; $stmt->close();
        if ($changed) {
            $clear=$conn->prepare('DELETE FROM password_reset_otps WHERE user_type=? AND user_id=?'); $clear->bind_param('si',$type,$id); $clear->execute(); $clear->close();
            $log=$conn->prepare('INSERT INTO admin_audit_log(admin_id,action_text) VALUES(?,?)'); $text="Reset $type password for account #$id"; $log->bind_param('is',$_SESSION['admin_id'],$text); $log->execute(); $log->close();
            $message = 'Temporary password saved. Any active reset codes were invalidated.';
        } else $error = 'The account was not found or the password was unchanged.';
    }
}
$students=$conn->query('SELECT id,full_name,student_id,email FROM students ORDER BY full_name'); $sellers=$conn->query('SELECT id,full_name,email,approval_status FROM sellers ORDER BY full_name');
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account Support | UniCanteen</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700&family=Poppins:wght@400;600&display=swap" rel="stylesheet"><style>:root{--blue:#2563eb;--muted:#64748b}*{box-sizing:border-box}body{margin:0;padding:24px;font:14px Poppins,sans-serif;background:#f1f5f9;color:#0f172a}.top,.card{background:#fff;border-radius:12px;box-shadow:0 2px 10px #0000000d}.top{padding:18px 22px;margin-bottom:18px}.top h1{margin:0;font:700 21px Montserrat}.top p,.card p{color:var(--muted)}.layout{display:grid;grid-template-columns:1.45fr .8fr;gap:18px}.card{padding:20px}h2{font:700 17px Montserrat;margin:0 0 8px}label{display:block;font-weight:600;font-size:12px;margin-top:14px}select,input{width:100%;padding:10px;margin-top:5px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}.submit{width:100%;margin-top:20px;padding:11px;border:0;border-radius:8px;background:var(--blue);color:#fff;font-weight:600;cursor:pointer}.notice{padding:10px 13px;border-radius:8px;margin-bottom:14px}.ok{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#b91c1c}.security{background:#fff7ed;color:#9a3412;padding:11px;border-radius:8px;font-size:12px}@media(max-width:760px){.layout{grid-template-columns:1fr}}</style></head><body><section class="top"><h1>Account Support</h1><p>Reset a verified student or seller account only after confirming identity.</p></section><?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif?><?php if($error):?><div class="notice error"><?=htmlspecialchars($error)?></div><?php endif?><main class="layout"><section class="card"><h2>Set a temporary password</h2><p>The user should change this password after signing in.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['admin_support_csrf'])?>"><label>Account type</label><select id="accountType" name="account_type"><option value="student">Student</option><option value="seller">Seller</option></select><label>Account</label><select name="account_id" id="studentAccounts"><?php while($u=$students->fetch_assoc()):?><option value="<?=$u['id']?>"><?=htmlspecialchars($u['full_name'])?> â€” <?=htmlspecialchars($u['student_id'])?></option><?php endwhile?></select><select name="account_id" id="sellerAccounts" disabled style="display:none"><?php while($u=$sellers->fetch_assoc()):?><option value="<?=$u['id']?>"><?=htmlspecialchars($u['full_name'])?> â€” <?=htmlspecialchars($u['email'])?></option><?php endwhile?></select><label>Temporary password</label><input type="password" name="temporary_password" minlength="8" required><p>Use uppercase, lowercase, a number, and a special character.</p><button class="submit">Save temporary password</button></form></section><aside class="card"><h2>Security</h2><p>Saving a temporary password immediately invalidates all active reset codes for the selected account.</p><div class="security">This action is recorded in the administrator audit trail.</div></aside></main><script>const type=document.getElementById('accountType'),students=document.getElementById('studentAccounts'),sellers=document.getElementById('sellerAccounts');type.onchange=()=>{const v=type.value==='seller';students.disabled=v;students.style.display=v?'none':'block';sellers.disabled=!v;sellers.style.display=v?'block':'none'}</script></body></html>
